import fr.ska.mesheures.BackupFiles;import java.io.*;import java.nio.file.*;
public class BackupFilesTest {public static void main(String[] args)throws Exception{File root=Files.createTempDirectory("hora-test").toFile();BackupFiles b=new BackupFiles(root);for(int i=0;i<12;i++)b.save(("version"+i).getBytes("UTF-8"));if(b.list().length!=7||!b.latest().equals("version11"))throw new AssertionError("rotation");Files.write(new File(root,"pending.tmp").toPath(),"interrompu".getBytes());if(!b.latest().equals("version11"))throw new AssertionError("temporaire");boolean bounded=false;try{BackupFiles.read(new ByteArrayInputStream(new byte[11]),10);}catch(IOException e){bounded=true;}if(!bounded)throw new AssertionError("limite");for(File f:root.listFiles())f.delete();root.delete();System.out.println("OK : 7 copies, dernière version, écriture interrompue ignorée, limite de taille");}}
